CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS departments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL UNIQUE, description TEXT, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS employees(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), employee_code TEXT UNIQUE NOT NULL, first_name TEXT NOT NULL, last_name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, phone TEXT, title TEXT, department_id UUID REFERENCES departments(id), manager_id UUID REFERENCES employees(id), role TEXT NOT NULL DEFAULT 'employee' CHECK(role IN ('employee','manager','hr','payroll','admin')), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','onboarding','offboarding','inactive')), hire_date DATE NOT NULL DEFAULT CURRENT_DATE, salary NUMERIC(12,2), location TEXT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), employee_id UUID REFERENCES employees(id) ON DELETE CASCADE UNIQUE, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL, active BOOLEAN DEFAULT true, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS onboarding_tasks(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), employee_id UUID REFERENCES employees(id) ON DELETE CASCADE, task TEXT NOT NULL, due_date DATE, completed BOOLEAN DEFAULT false, completed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS shifts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), employee_id UUID REFERENCES employees(id) ON DELETE CASCADE, name TEXT NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, timezone TEXT DEFAULT 'Asia/Kolkata', effective_date DATE NOT NULL DEFAULT CURRENT_DATE);
CREATE TABLE IF NOT EXISTS attendance(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), employee_id UUID REFERENCES employees(id) ON DELETE CASCADE, event_type TEXT CHECK(event_type IN ('clock_in','clock_out','correction')), event_time TIMESTAMPTZ NOT NULL, source TEXT DEFAULT 'manual', note TEXT, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS leave_requests(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), employee_id UUID REFERENCES employees(id) ON DELETE CASCADE, leave_type TEXT NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, days NUMERIC(5,2) NOT NULL, reason TEXT, status TEXT DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','cancelled')), approver_id UUID REFERENCES employees(id), decided_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT now(), CHECK(end_date >= start_date));
CREATE TABLE IF NOT EXISTS leave_balances(employee_id UUID REFERENCES employees(id) ON DELETE CASCADE, leave_type TEXT, balance NUMERIC(6,2) DEFAULT 20, PRIMARY KEY(employee_id,leave_type));
CREATE TABLE IF NOT EXISTS salary_components(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), employee_id UUID REFERENCES employees(id) ON DELETE CASCADE, component TEXT NOT NULL, amount NUMERIC(12,2) NOT NULL, kind TEXT CHECK(kind IN ('earning','deduction')), active BOOLEAN DEFAULT true);
CREATE TABLE IF NOT EXISTS payroll_runs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), period TEXT NOT NULL UNIQUE, status TEXT DEFAULT 'prepared', created_by UUID REFERENCES employees(id), created_at TIMESTAMPTZ DEFAULT now(), completed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS payslips(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), payroll_run_id UUID REFERENCES payroll_runs(id) ON DELETE CASCADE, employee_id UUID REFERENCES employees(id), gross NUMERIC(12,2), deductions NUMERIC(12,2), net NUMERIC(12,2), details JSONB DEFAULT '{}', UNIQUE(payroll_run_id,employee_id));
CREATE TABLE IF NOT EXISTS performance_reviews(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), employee_id UUID REFERENCES employees(id), reviewer_id UUID REFERENCES employees(id), period TEXT, rating NUMERIC(3,1), feedback TEXT, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS documents(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), employee_id UUID REFERENCES employees(id), name TEXT NOT NULL, category TEXT, storage_key TEXT, uploaded_by UUID REFERENCES employees(id), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), actor_id UUID REFERENCES employees(id), action TEXT NOT NULL, entity TEXT, entity_id TEXT, metadata JSONB DEFAULT '{}', created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_employee_department ON employees(department_id); CREATE INDEX IF NOT EXISTS idx_attendance_employee_time ON attendance(employee_id,event_time); CREATE INDEX IF NOT EXISTS idx_leave_status ON leave_requests(status); CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_logs(created_at DESC);
